CREATE TABLE IF NOT EXISTS "app_guard_settings" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"user_id" uuid NOT NULL UNIQUE REFERENCES "users"("id") ON DELETE cascade,"enabled" boolean NOT NULL DEFAULT false,"max_temporary_minutes" integer NOT NULL DEFAULT 10,"strictness" varchar(16) NOT NULL DEFAULT 'balanced',"created_at" timestamp DEFAULT now() NOT NULL,"updated_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "app_guard_restricted_apps" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE cascade,"package_name" varchar(255) NOT NULL,"display_name" varchar(255),"created_at" timestamp DEFAULT now() NOT NULL,"updated_at" timestamp DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_app_guard_user_package" ON "app_guard_restricted_apps" ("user_id","package_name");
CREATE TABLE IF NOT EXISTS "app_guard_access_decisions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE cascade,"package_name" varchar(255) NOT NULL,"decision" varchar(12) NOT NULL,"category" varchar(24) NOT NULL,"confidence" real NOT NULL,"reason" varchar(500) NOT NULL,"duration_minutes" integer,"expires_at" timestamp,"created_at" timestamp DEFAULT now() NOT NULL);
